const fs=require('fs'),path=require('path'),vm=require('vm');const root=path.resolve(__dirname,'..');
const context=vm.createContext({window:{},localStorage:{getItem:()=>null},console});vm.runInContext(fs.readFileSync(path.join(root,'dist/ship-catalog.js'),'utf8'),context);context.window=context;let game=fs.readFileSync(path.join(root,'dist/game.js'),'utf8');vm.runInContext(game.slice(0,game.indexOf("document.addEventListener('click'")),context);
const data=vm.runInContext('({buildings:BUILDINGS,tech:TECH_TREE,scans:SCAN_TYPES,structures:STRUCTURE_DEFS,ships:SHIPS})',context);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=vm.runInContext('freshState()',context);defaults.galaxy.forEach((p,i)=>{p.coords='07:'+String(4+Math.floor(i/10)).padStart(2,'0')+':'+String(i%10+1).padStart(2,'0');p.ships=vm.runInContext('normalizeFleet('+JSON.stringify(p.ships||{})+')',context);});defaults.alliance.members.forEach(m=>{m.rank={"High Commander":"HC",Commander:"Officer"}[m.rank]||m.rank;const p=defaults.galaxy.find(p=>p.name===m.planet);if(p){m.planetId=p.id;m.coords=p.coords;}});fs.writeFileSync(path.join(root,'worker/default-round.json'),JSON.stringify(defaults));
const cost=c=>Object.entries(c).filter(([,n])=>n).map(([r,n])=>n.toLocaleString('en-US')+' '+r).join(' · ')||'None';
const sections=[
['start','Getting started',`<p>Starfall Command is a planetary strategy practice game. Build your economy, research new technology, manufacture ships, explore galaxies and coordinate with your alliance. Your practice round runs on this device; scans are stored centrally so players can share intelligence.</p><h3>Your first session</h3><ol><li>Open the portal and sign in with your game account.</li><li>Check <strong>Overview</strong> for resources, population, current projects and ships.</li><li>Use <strong>Mining</strong> to expand asteroid production, then improve refineries and factories in Construction.</li><li>Assign population to the activities you need and begin a research project.</li><li>Build a Wave Amplifier before attempting scans. Enable sharing under Planet Settings → Quick Actions if you want other players to see your scans.</li><li>Use the Galaxy Browser to find planets and open their shared intelligence.</li></ol><div class="notice">The planets, economy and combat are a practice simulation. A shared scan is a report from a player's practice round, not a live Planetarion universe record.</div>`],
['navigation','Portal, login & navigation',`<p>The portal is the starting point. <strong>Enter game</strong> opens your practice round after login; the manual can be read without a game login by visitors who already have access to this site.</p><p>The left menu groups Military, Foreign Affairs, Archive and Administration. Development shortcuts at the top open Mining, Construction, Research, Population and Planet Settings. <strong>Leave unfolded</strong> keeps the menu groups expanded.</p><p>Archive contains <strong>the Miday array</strong>, News Log and Quests. Portal, Manual and Sign out links remain available from the game.</p><h3>Account security</h3><p>Passwords are stored as salted hashes. Login uses a secure server session; signing out ends that session. Five unsuccessful attempts temporarily lock an account for 15 minutes. Signing out does not erase your browser's practice round.</p>`],
['governments','Government lookup & production bonuses',`<p>Reference: <a href="https://game.planetarion.com/manual.pl?page=governments">Planetarion governments</a>, <a href="https://game.planetarion.com/manual.pl?page=population">Population</a> and <a href="https://game.planetarion.com/manual.pl?page=formulae">Formulae</a>.</p><div class="table-wrap"><table class="ship-stats-table"><thead><tr><th>Government</th><th>Production output bonus</th><th>Production cost discount</th></tr></thead><tbody><tr><td>Corporatism</td><td>0%</td><td>0%</td></tr><tr><td>Democracy</td><td>0%</td><td>8%</td></tr><tr><td>Nationalism</td><td>−10%</td><td>0%</td></tr><tr><td>Socialism</td><td>+20%</td><td>0%</td></tr><tr><td>Totalitarianism</td><td>−10%</td><td>6%</td></tr><tr><td>Anarchy / revolution</td><td>−20%</td><td>0%</td></tr></tbody></table></div><h3>Apply to running ship orders</h3><p>Population → Shipwrights supplies the population percentage bonus. Output uses the additive factor <code>1 + (population bonus + government bonus) / 100</code>. Starfall retains its existing factory build-point base and round multiplier; this update implements the manual’s production bonuses, not the entire Planetarion production-unit economy. Factory allocation remains attached to each numbered order.</p><p>Population and government output changes update the current order’s ETA and the next tick’s work immediately, without resetting progress or changing its paid costs. Government cost discounts apply only when placing a new order and are shown in the price preview. Cancellation refunds half of the cost actually paid.</p><h3>Government selection</h3><p>Choose a government under Population. First formation within the first 168 ticks is free. A later formation or a change starts a 72-tick revolution, using the Anarchy production penalty. This implementation covers production; mining, research and construction government effects are not applied here. Covert ops separately uses the stealth and alert modifiers.</p>`],
['ticks','Ticks, protection & saved progress',`<p>A tick advances production, population, research, construction, shipbuilding, fleet missions and temporary alliance effects. The default tick interval is one hour; the round lasts 672 ticks and has 24 ticks of protection unless changed in Admin.</p><p>The countdown follows the configured interval. <strong>Simulate tick</strong> advances a practice tick immediately. When returning after an absence, the local clock catches up in bounded steps.</p><p>Browser saves preserve the current practice round. The central database stores scan reports and sharing preferences independently. <strong>Reset</strong> replaces the browser's round; it is not a password reset or a deletion of your game account.</p><p>Normal planet attacks are blocked while protection is active. Structure planets have their own war requirement.</p>`],
['economy','Resources, asteroids & income',`<p>Metal, Crystal and Eonium pay for development, ship production, scans and self exile. Each resource has an asteroid field, a refinery and a resource reserve.</p><h3>Income calculation</h3><p>Core Mining levels 0–4 provide respectively <strong>1,000; 3,500; 7,000; 12,500; 20,000</strong> base income for each resource. Every asteroid adds 250 per tick, and every matching refinery adds 1,100.</p><p>The base amount is multiplied by mining workforce and finance bonuses, the round income multiplier and applicable alliance effects. Each Finance Centre adds 0.5%. Your displayed resource rate reflects these factors and any enabled alliance tax.</p><h3>Mining capacity</h3><p>Heavy Cargo Transfers increases asteroid capacity. The progression is 100, 200, 300, 500, 750, 1,000, 1,250, 1,500, 2,000, 2,500, 3,000, 3,500, 4,500, 5,500, 6,500, 8,000 and 10,000 asteroids.</p><p>Planet value includes holdings such as resources, ships, buildings and asteroids; the practice score adds earned experience to that value. The game shows its current calculation in the planet and galaxy views.</p>`],
['population','Population & workforce',`<p>The five workforce assignments are Mining, Research, Construction, Shipwright and Security. The assignments must total exactly <strong>100%</strong> before they can be applied.</p><p>Mining improves resource output. Research staffing scales research points; Construction scales construction units; Shipwright staffing scales factory production. Security is a dedicated allocation in the practice workforce model.</p><p>Population increases on ticks. The default practice allocation is 40% Mining, 20% Research, 20% Construction, 15% Shipwright and 5% Security. Change the allocation as your immediate needs change, then press <strong>Assign workforce</strong>.</p>`],
['construction','Buildings & construction',`<p>Construction spends resources and progresses through construction units. One active order can be accompanied by queued orders. The game shows the remaining work and estimated ticks; cancel controls describe the refund available for that order.</p><p>Construction output is based on staffing: a 20% construction allocation provides 100 construction units per tick. Building costs and capacity may change with development, so the order card is the authoritative price before purchase.</p><div class="table-wrap"><table><thead><tr><th>Building</th><th>Purpose</th><th>Base resource cost</th><th>Work</th></tr></thead><tbody>${Object.entries(data.buildings).map(([id,b])=>`<tr><td><span class="manual-building-name">${structureIcon(id)}${esc(b.name)}</span></td><td>${esc(b.desc)}</td><td>${esc(cost(b.cost))}</td><td>${b.cu} CU</td></tr>`).join('')}</tbody></table></div>`],
['research','Research branches & progression',`<p>Select one research project at a time. Each tick adds research points until the next level completes. The branch card shows the next unlock, progress and approximate duration.</p><p>Research output combines the laboratory count, research staffing and the configured round multiplier. Laboratory density adds a bonus capped at 20%. At 20% research staffing, the underlying output starts from <code>12 + 24 × laboratories</code> before bonuses.</p>${data.tech.map(t=>`<details><summary>${esc(t.name)} · ${t.max} levels</summary><p>${esc(t.desc)}</p><ol>${t.levels.map(level=>'<li>'+esc(level)+'</li>').join('')}</ol></details>`).join('')}`],
['ships','Factories, ship production & fleets',`<p>Production lists the ships for your planet's race. An order requires the matching hull research, the correct factory and enough resources. Enter a quantity to see the total cost before ordering.</p><p>Light factories build Fighters and Corvettes. Medium factories serve Frigates, Destroyers and Cruisers; Heavy factories build Battleships. Assign owned factories to production to make use of their throughput. Queue and cancel controls manage ongoing orders.</p><p>Autofill buttons calculate the ships needed to reach a target fleet total, rather than ordering that many additional ships.</p><h3>Fleet management</h3><p>Your ships are divided between the Base fleet and Fleet 1–3. Transfer ships into a field fleet before launching a mission. Launching removes those ships from the ready fleet and creates an outbound mission. Recall controls send active missions home.</p><p>Baseline travel takes five ticks. Space Travel research removes one tick per two levels, and an active alliance Transwarp Hub can remove one more. Travel time never drops below one tick.</p><h3>Ship roster</h3><p>Every race has a distinct roster and artwork. Production cards expose targeting, initiative, guns, damage, armour, role, cloak, ETA and cost. Use those current cards and the battle calculator when composing a fleet.</p>`],
['combat','Combat, targeting & defence',`<p>Attack, defence and related fleet operations use the practice combat resolver. Ship class targeting, initiative, damage and armour determine how engagements unfold. Cloaked units and specialised roles may affect what reports show.</p><p>Planet protection blocks ordinary attacks until the protection period ends. Hostile alliance structure planets require a declared war with their owner before they can be attacked.</p><p>Base fleet behaviour can be set to Stay Home and Fight or Run and Hide. Alliance defence calls identify a planet, hostile ETA and notes; select a ready fleet to respond.</p><h3>Battle calculator</h3><p>Under Alliance, paste ship reports into the attacker or defender side, parse their counts and calculate. The result shows starting fleets, losses and survivors. You can also copy counts and results. A calculator result is a practice estimate rather than a guarantee of a live game's outcome.</p>`],
['scans','Waves & scan types',`<p>A Wave Amplifier is required to scan. The first amplifier enables scanning; each additional amplifier reduces costs by 0.3%, capped at a 75% discount. Each listed base cost is paid in <strong>each of Metal, Crystal and Eonium</strong>.</p><p>Use the X:Y:Z fields, or enter compact Galaxy:slot coordinates. <code>2:7</code> selects galaxy 2, planet slot 7 in your home sector; <code>07:04:02</code> is the full form. Paste one coordinate into the paste box, apply it, then choose a scan type to launch.</p><div class="table-wrap"><table><thead><tr><th>Scan</th><th>Scan research level</th><th>Base cost each</th><th>Information</th></tr></thead><tbody>${data.scans.map(([id,name,amount,desc],i)=>`<tr><td>${esc(name)}</td><td>${i}</td><td>${amount.toLocaleString('en-US')}</td><td>${esc(desc)}</td></tr>`).join('')}</tbody></table></div><p>Landing Scans require a fleet at ETA 1. Incoming Scans require an inbound enemy fleet. The scan cards show the research needed, current cost and whether the action is available.</p><p>The appointed scanner, an Alliance Scanner or the Alliance HC can use the available funding controls. Galaxy sweeps require the appropriate scanner or Minister of War permission and enough funding for every target. These permissions remain separate from the option to share reports with everyone.</p>`],
['miday','the Miday array & central sharing',`<p><strong>Archive → the Miday array</strong> is the central scan archive. Every report has an icon identifying its scan type, target, tick and saved time. Reports remain available for two weeks.</p><h3>Store privately or share with all players</h3><ol><li>Open Planet Settings.</li><li>Under Quick Actions, find <strong>Enable sharing of scans to all people</strong>.</li><li>Enable it to make your centrally stored scans visible to other game visitors.</li><li>Disable it to hide your scans from the shared archive. The central copies remain private.</li></ol><p>Sharing starts disabled. Your sign-in identifies the owner of your reports; another player cannot overwrite or delete them. Deleting a saved scan also removes its central copy.</p><h3>Search and type filters</h3><p>Search by planet name, coordinates, scan name or words from the report. Each scantype checkbox can be switched on or off, just like news categories. All scan types enables or disables the complete set. Use Refresh Scans for the latest records and Load More Scans when more results are available.</p><h3>Scans for one planet</h3><p>The archive button next to P, D, A and U in Galaxy Browser opens all shared scans for that planet, with all types selected. Clear Planet Filter returns to the wider archive.</p><h3>Anonymous reports</h3><p>An anonymous report hides its coordinate field and coordinate strings in the shared report text. Anonymous scans are excluded from coordinate-based planet lookups. Their type and target name remain visible.</p><p>Everyone means everyone who can access this Site and sign into the game. The site's existing access policy is not changed by scan sharing.</p>`],
['galaxies','Galaxies, slots & self exile',`<p>Galaxy Browser accepts X:Y coordinates and shows tracked practice planets or deterministic simulated galaxies. Every galaxy displays exactly <strong>15 slots</strong>: 1–10 are planet slots and 11–15 are reserved for alliance stronghold structures.</p><p>Empty structure slots display <strong>Empty / Reserved</strong>, even where no stronghold exists. Structure rows have their own labels, and an occupied planet slot is never used for a stronghold structure.</p><h3>Exile Option</h3><p>Planet Settings replaces Layout Module with Exile Option. Yes is unchecked by default. Checking it shows confirmation and the exact resource charge before your planet moves to a free slot in a different galaxy. All fleets must be home and you must be able to pay.</p><p>The charge is shown separately for each resource. It rises with your previous self-exile count and your galaxy's counted score relative to the average. Free planets pay twice the paid-planet cost. This game uses tracked local galaxy scores to apply the <a href="https://game.planetarion.com/manual.pl?page=formulae" target="_blank" rel="noopener">Planetarion self-exile formula</a>.</p><p>Payment goes into the galaxy fund of the galaxy you leave. Your fleet, buildings, research and alliance membership remain. The practice relocation is immediate, rather than waiting for one of the next four ticks as in Planetarion.</p><p>Counted score records progress gained in the current galaxy. Score brought in through exile does not count as newly earned galaxy score.</p>`],
['alliance','Alliances, funds & strongholds',`<p>Alliance pages cover members, recruitment, defence calls, the battle calculator, alliance funds, fortress placement, structures, relations and logs. The current High Commander manages fortress placement, roles and alliance structures.</p><p>Accepted applicants begin as Recruits. Members can hold Member, Scanner or Officer roles; the HC position remains with its current holder in this practice round. The alliance supports up to 40 members.</p><h3>Create an alliance and assign practice planets</h3><p>Open Alliance, enter a unique name and a tag of 2–8 letters or numbers, then choose Create Alliance. You become High Commander. Five unassigned practice planets are added when the local 40-planet capacity allows. Use Administration → Planets to assign them through the alliance selector. The wrench next to tracked planets opens their editor directly. Sector, galaxy and slot selectors let the administrator reposition a planet without occupying an existing planet slot.</p><h3>Alliance Intel</h3><p>Alliance Intel has a separate galaxy browser with its own coordinates, 15 slots, planet and note search, and a dossier for every populated slot. Assess planets as Friendly, Watch or Hostile and save a note. Reports combine your own saved scans with centrally shared reports for those coordinates. Notes and assessments are saved with this device’s practice alliance. Ranks controls who may view intel and edit assessments.</p><h3>Ranks and permissions</h3><p>The Ranks tab controls every alliance option for HC, Officer, Scanner, Member and Recruit. By default Members may exchange fund reserves, while only HC can configure minimum reserves and permissions. Each fund exchange must leave all three resulting reserves at or above their configured minimum. The player or game admin with permission access can save a custom role matrix or restore defaults.</p><h3>Funds and taxes</h3><p>Donate to Alliance Fund deducts a positive whole amount from your planet and schedules it to arrive after 8 ticks. Combined donations of each resource are capped at two ticks of income per 24 hours. Exchange Resources converts personal reserves, or alliance reserves according to rank permissions, with a 5% fee rounded up to a whole resource unit. For example, giving 1,000 Metal receives 950 Crystal. The result stays in the selected account.</p><p>Alliance tax is configurable from 0% to 5%; a planet can enable or disable its contribution in Planet Settings. Donations are limited and scheduled rather than credited immediately. Galaxy Fund is separate and has its own permissions and donation controls.</p><h3>Fortress benefits</h3><p>Only alliance members residing in the stronghold galaxy receive the fortress's <strong>0.25% passive resource bonus</strong> and its free Wave Distorter every 24 hours. Moving the fortress after the first tick starts a 24-hour anarchy period, with an alliance-wide 2% income penalty.</p><p>A stronghold must be placed in a galaxy that contains alliance members. Its structures occupy only slots 11–15.</p>${Object.entries(data.structures).map(([id,d])=>`<details><summary>${structureIcon(id)}${esc(d.name)}</summary><p>${esc(d.desc)}</p><p>Cost: ${Math.round(d.share*100)}% of calculated daily alliance tax income. ${d.cooldown?'Cooldown: '+d.cooldown+' ticks.':'Repeatable.'}</p></details>`).join('')}<p>Active structures expire according to their displayed tick or hour duration. The five-amplifier and five-distorter megastructure rewards retain their alliance-wide scope; those differ from the fortress's location-specific daily reward.</p>`],
['politics','Politics & galaxy governance',`<p>Galaxy politics handles commander votes, minister appointments, a message and banner, trust policies, fund permissions and exile votes. Minister roles cover Communication, Development, War, Economics and scanning.</p><p>Galaxy exile votes are different from voluntary self exile. They require funding and minister approvals, and the practice system limits them to two in a 200-tick window. Review the target, reason and displayed cost before opening a vote.</p><p>Voluntary self exile moves you into another galaxy and resets the local political context and galaxy-fund view to your new location. Alliance membership is preserved.</p>`],
['archive','News, quests & troubleshooting',`<p>News Log records events from your practice round. Category checkboxes switch Economy, Development, Research, Fleet, Intelligence, Alliance, Politics and System events on or off. The search field narrows the visible messages.</p><p>Quests track supported local objectives. Completed quests can be claimed once per round for 500 Metal, 350 Crystal and 200 Eonium. Off-site objectives are marked unavailable.</p><details><summary>Why is a scan unavailable?</summary><p>Check that you have a Wave Amplifier, the required scan research, an existing target at the selected coordinates, the necessary special fleet condition and enough resources in the selected funding source. Alliance Scans must be enabled to launch scans.</p></details><details><summary>Why is the Miday array empty?</summary><p>No matching player may have enabled sharing, or your filters may exclude the results. Enable all types, clear the planet filter and search text, then refresh. New databases begin empty; preview example reports are never published.</p></details><details><summary>Why did sharing fail?</summary><p>Confirm you are signed in and your connection is working. The page shows database errors instead of reporting a successful save. Refresh Scans reconnects to the central service.</p></details><details><summary>Why does a galaxy show Empty / Reserved?</summary><p>Those slots are reserved for stronghold structures, whether or not that galaxy currently contains a stronghold. They are not extra planet slots.</p></details><details><summary>Can I edit the practice round?</summary><p>Administration includes round configuration, planet editing, ship statistics and JSON snapshot tools. Export a snapshot before major changes. Those tools affect your browser's simulated round and do not turn practice planets into live multiplayer planets.</p></details>`],
];
sections.push(['havoc','Administration & Havoc', '<p>Round setup configures the local round. Planet tools can unlock every research branch or add one of each construction to your current planet.</p><h3>Havoc control board</h3><p>Configure research levels, construction counts, resources, asteroids, base-fleet totals per class and minutes per tick. Apply to all immediately sets those values on every saved practice planet. Smaller tick intervals make the game faster. Class totals are distributed across each race’s ship types; active missions retain their fleets.</p><p>Reset to previous restores the state from before the most recent Havoc application, including resources, asteroids, fleets and gamespeed. The backup survives page reloads. It is a single-step undo.</p><h3>Dummy alliance members</h3><p>Signed-in game admins can select an unassigned dummy in Alliance → Members and add it to the alliance, or create a new dummy member. High Commander rank alone does not show this admin control. Administration → Planets also offers the alliance selector and Add Dummy Member.</p>'], ['lore','The Vesper Chronicles','<p>When the Starfall collapsed the old jumpgate network, five civilisations found themselves stranded around the Vesper Reach. Terran shipyards rebuilt the trade routes. Cathaar listening posts followed signals through the dust. Xandathrii navigators mapped the silent corridors, while Zikonian foundries and Eitraides archives preserved the tools needed to survive.</p><p>The eleven command offices issued a shared charter: restore the mines, protect the colonies, and uncover the last transmission of the Miday beacon. No fleet has yet reached its source. Every commander who rebuilds a world brings the Reach one jump closer.</p>']);
function structureIcon(id){return vm.runInContext('structureGlyph('+JSON.stringify(id)+')',context);}
const categoryIcons={governments:'POLITICS',start:'SYSTEM',navigation:'SYSTEM',ticks:'SYSTEM',economy:'ECONOMY',population:'POLITICS',construction:'DEVELOPMENT',research:'RESEARCH',ships:'FLEET',combat:'FLEET',scans:'INTELLIGENCE',miday:'INTELLIGENCE',galaxies:'SYSTEM',alliance:'ALLIANCE',politics:'POLITICS',archive:'INTELLIGENCE',havoc:'DEVELOPMENT',lore:'SYSTEM'};
sections.push(['covert','Covert operations',`<h3>Military command</h3><p>Open Military → Covert ops to train or dismiss agents and guards, select a practice target, choose an unlocked operation and send agents. Results are instantaneous and appear in the blue Covert ops news category.</p><h3>Research and launch checks</h3><p>The existing covert research branch unlocks nine operations. Protection, paused ticks, closed targets, insufficient agents, insufficient resources and exhausted stealth prevent launch. Mission cost is 500 of each resource per agent, also on failure.</p><h3>Scope and rates</h3><p>Target changes affect this browser’s practice snapshot; this is not a server-authoritative multiplayer attack system. Training and wages are explicitly shown as Starfall practice rates. Mission rules are based on the <a href="https://game.planetarion.com/manual.pl?page=covertops">Planetarion covert manual</a>.</p><h3>Bonuses</h3><p>Quests → Bonuses shows current unused resources, asteroids, RP and CU. The startup grant is imported once: 2,000,000 per resource plus 7,000 CU and 8,000 RP adjusted for race. Historical loyalty defaults to zero because previous-round history is unavailable. <a href="https://game.planetarion.com/manual.pl?page=formulae">Startup rules</a>.</p>`]);
const manualSteps=items=>'<div class="manual-flow">'+items.map(([number,title,text])=>'<article><span class="manual-step-number">'+number+'</span><h3>'+title+'</h3><p>'+text+'</p></article>').join('')+'</div>';
sections.push(['order-drafts','Draft orders: ships & asteroids','<p>Ship Production and Mining share the same two-stage ordering workflow. Drafts persist in the browser and do not charge resources.</p>'+manualSteps([['01','Choose an amount','Enter the number of ships or asteroids. For ships, choose Base or Fleet 1–3 as the delivery destination.'],['02','Add to order','Build a draft from several ship types or resource types. Remove entries or clear the draft before confirming.'],['03','Order all','The whole bill is checked against resources, research and capacity. Failure preserves the draft without partial payment.'],['04','Delivery','Ships arrive in their selected fleet on completion. Asteroids are initiated immediately using their current rising prices.']])+'<h3>Independent orders</h3><p>Order now remains available on every card. Ship orders still use one active and one queued order; asteroid orders retain mining capacity limits.</p>']);
sections.push(['bonuses','Quest rewards, medals & bonus allocation','<p>Each supported quest shows its lore, exact reward and progress before completion. A completion medal marks a reached goal; claiming upgrades it to gold. Every quest is claimable once per round. Planet Settings has an opt-in Quest automation control that claims completed rewards into the bank; allocation remains manual. Claim all completed is available for each category and at the end of the board; it only collects reached, unclaimed goals.</p>'+manualSteps([['01','Complete the charter','Meet the displayed objective. Unsupported objectives are explicitly marked unavailable.'],['02','Claim the reward','The reward enters the unused bonus bank; it is not silently applied.'],['03','Open Bonuses','The Bonuses tab is alongside Quest board, using the same tab layout as Alliance.'],['04','Allocate','Accept resources/asteroids or allocate whole RP/CU amounts to branches and buildings. Partial progress and unused points persist.']])+'<h3>Startup grant</h3><p>A one-time startup grant supplies 2,000,000 of each resource. Its RP/CU totals depend on the race at import. No previous-round loyalty bonus is invented.</p><div class="table-wrap"><table class="table"><thead><tr><th>Race</th><th>Research points</th><th>Construction units</th></tr></thead><tbody><tr><td>Terran</td><td>7,600</td><td>8,750</td></tr><tr><td>Cathaar</td><td>8,800</td><td>7,350</td></tr><tr><td>Xandathrii</td><td>8,400</td><td>7,000</td></tr><tr><td>Zikonian</td><td>7,600</td><td>8,050</td></tr><tr><td>Eitraides</td><td>8,000</td><td>7,700</td></tr></tbody></table></div><p><a href="https://game.planetarion.com/manual.pl?page=formulae">Startup formula</a> · <a href="https://game.planetarion.com/manual.pl?page=races">Race adjustments</a></p><h3>Temporal command quests</h3><p>The first manual start, first stop and first restart each unlock one asteroid of every type. Their lore appears on the board; claim and accept through Bonuses. Scheduled starts award no quest progress.</p>']);
sections.push(['ticker','Ticker, clocks & scheduled starts','<p>Administration → Round state contains the ticker control panel. This is a browser-practice ticker: it runs while the game is open and catches up at most 24 ticks after inactivity.</p>'+manualSteps([['▶','Start / restart','A fresh interval is scheduled. A manual action can unlock the first-start or first-restart quest once.'],['Ⅱ','Pause','Automatic ticks freeze and interval progress stays still. Run one tick is an explicit manual action.'],['■','Stop','Stops automatic ticks and resets the displayed interval bar. The first stop has a one-time quest reward.'],['◷','Schedule','Choose a future local date/time and save. The game must be open when processing the schedule; automatically starting never unlocks ticker quests.']])+'<h3>Time information</h3><p>The header shows current tick, next-tick countdown, an interval progress bar, a local 24-hour clock and synchronized server UTC. Page load measures browser navigation time; Server RTT measures the full network round trip. These clocks do not mean the simulation runs as a server-authoritative ticker.</p><h3>Game updates</h3><p>Starts, pauses and stops confirm with a toast and prominent yellow/black entries in Recent signals and News Log. Toggle the Game updates category in the news filters.</p>']);
sections.push(['staff-news','Staff tools & publishing news','<p>The portal Staff panel is restricted to game admins. Tabs separate round tools, user assignments, news articles and reset.</p>'+manualSteps([['01','Compose','Choose one of five update categories, enter a title, synopsis and article text. Font controls format selected text.'],['02','Publish','Publishing creates a central database article and a permanent article link.'],['03','Edit / save','The staff-made article list sits below the editor. Edit loads the article and exposes Save changes; saving updates the same entry.'],['24h','Pinned news','New staff articles join portal News posts and the archive. For 24 hours a pin badge and highlighted border keep them prominent; afterwards their normal layout and date order return.']])+'<h3>Category colors</h3><div class="manual-category-key"><span style="--key:#caa0ff">Game mechanics</span><span style="--key:#85caff">Round update</span><span style="--key:#83dfa3">Stats update</span><span style="--key:#ff939c">Error update</span><span style="--key:#ffe279">Pause / resume</span></div><h3>Reset</h3><p>The confirmed round reset recreates planets and alliances and clears intel, scans, quests, rewards and game news. All tax and sharing preferences reset unchecked. Accounts and passwords remain.</p>']);
sections.push(['races','Races & bonuses','<p>Compare civilisations, fleet doctrine and bonus reference values. Applied startup bonuses are marked separately.</p><div id="manualRaceEncyclopedia"></div><p><a href="/#race-encyclopedia">Back to the portal race encyclopedia →</a></p>']);
const icon=category=>'<span class="theme-icon" aria-hidden="true">'+vm.runInContext('newsIcon('+JSON.stringify(category)+')',context)+'</span>';
