const shipStats='<div class="ship-stats-reference" id="ship-stats"><h3>Ship stats</h3><p>Starfall preset ship values. Column order and race backgrounds follow the <a href="https://game.planetarion.com/manual.pl?page=stats" target="_blank" rel="noopener">Planetarion stats reference</a>. Admin ship overrides in your practice round are shown in the game’s Production cards.</p><label class="fleet-filter" for="manualStatsRace">Race tables<select id="manualStatsRace"><option value="all">All races</option>'+races.map(r=>'<option>'+r+'</option>').join('')+'</select></label>'+races.map(r=>'<div class="table-wrap ship-stat-race" data-stat-race="'+r+'" style="--stats-bg:'+statsColors[r]+'"><table class="ship-stats-table"><caption>'+r+'</caption><thead><tr>'+headers.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+Object.values(data.ships).filter(d=>d.race===r).map(d=>{const targets=Array.isArray(d.target)?d.target:[],cells=[d.class,...[0,1,2].map(i=>targetAbbr[targets[i]]||targets[i]||'-'),d.type||'Norm',d.cloaked?'Y':'N',d.initiative,d.guns,d.armour,d.damage||'-',d.er,d.cost.metal,d.cost.crystal,d.cost.eonium,d.ac,d.dc,d.eta];return '<tr><th scope="row"><span class="stat-ship-name"><img src="'+shipAsset(r,d.class)+'" loading="lazy" alt="'+esc(d.name)+' · '+r+' '+d.class+'"><span>'+esc(d.name)+'</span></span></th>'+cells.map(v=>'<td>'+esc(v??'-')+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div>').join('')+'<div class="stats-key"><b>Column key</b><p>T1–T3: target priority. Cl: cloak (Y/N). Init: initiative. Gun: guns. Arm: armour. Dmg: damage. M/C/E: Metal, Crystal, Eonium costs. A/C and D/C: armour and damage relative to cost. E/R and ETA use the catalogue values.</p><p>Fi: Fighter · Co: Corvette · Fr: Frigate · De: Destroyer · Cr: Cruiser · Bs: Battleship · Ro: Asteroids · St: Structures.</p></div></div>';
const fleetGallery='<div class="fleet-reference"><div class="section-bar"><span>FLEET RECOGNITION GUIDE</span><small>RACE ARTWORK · SIX CLASSES</small></div><label class="fleet-filter" for="manualShipRace">Race roster<select id="manualShipRace"><option value="all">All races</option>'+races.map(r=>'<option>'+r+'</option>').join('')+'</select></label><div class="manual-ship-grid">'+races.flatMap(r=>shipClasses.map(cls=>{const ship=Object.values(data.ships).find(d=>d.race===r&&d.class===cls);return '<figure class="manual-ship" data-ship-race="'+r+'"><img loading="lazy" src="'+shipAsset(r,cls)+'" alt="'+r+' '+cls+' artwork"><figcaption><span>'+r+'</span><b>'+cls+'</b><small>'+(ship?esc(ship.name)+' · '+esc(ship.type||'Norm'):'Class recognition artwork')+'</small></figcaption></figure>';})).join('')+'</div></div>';
